files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --light-off: #2a2a4a;
  --light-on: #e94560;
  --focus: #f4d35e;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 3px solid var(--accent);
  border-radius: 12px;
  padding: 24px 20px 20px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.4);
}

.title {
  margin: 0 0 20px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.bpm-section {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

.bpm-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 100px;
}

#bpm-value {
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.bpm-unit {
  font-size: 0.75rem;
  color: var(--muted);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.beat-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}

.beat-light {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--light-off);
  border: 4px solid var(--muted);
  transition: background 80ms, box-shadow 80ms, border-color 80ms;
}

.beat-light.active {
  background: var(--light-on);
  border-color: var(--focus);
  box-shadow: 0 0 24px var(--light-on), 0 0 48px var(--light-on);
}

.beat-counter {
  font-size: 1.125rem;
  color: var(--muted);
}

#beat-count {
  color: var(--text);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn {
  font: inherit;
  font-size: 1rem;
  font-weight: 700;
  border: 3px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  padding: 12px 20px;
  min-width: 80px;
  transition: transform 80ms, background 120ms, border-color 120ms, box-shadow 120ms;
}

.btn-small {
  padding: 8px 16px;
  min-width: 48px;
  font-size: 1.25rem;
  background: var(--bg);
  color: var(--text);
  border-color: var(--muted);
}

.btn-small:hover {
  border-color: var(--accent);
  background: var(--card);
}

.btn-small:active {
  transform: translateY(2px);
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover {
  background: #f0576f;
}

.btn-primary:active {
  transform: translateY(2px);
  background: #c7304a;
}

.btn-secondary {
  background: var(--bg);
  color: var(--text);
  border-color: var(--muted);
}

.btn-secondary:hover {
  border-color: var(--accent);
}

.btn-secondary:active {
  transform: translateY(2px);
  background: var(--card);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.hint {
  margin: 0;
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.4;
}

@media (max-width: 360px) {
  .card {
    padding: 20px 14px 16px;
  }
  .title {
    font-size: 1.25rem;
  }
  #bpm-value {
    font-size: 2rem;
  }
  .btn {
    padding: 10px 14px;
  }
}

(function () {
  'use strict';

  var MIN_BPM = 40;
  var MAX_BPM = 200;

  var bpm = 120;
  var running = false;
  var beatCount = 0;
  var timerId = null;
  var nextTickAt = 0;
  var lightTimeout = null;

  var bpmValueEl = document.getElementById('bpm-value');
  var beatCountEl = document.getElementById('beat-count');
  var beatLightEl = document.getElementById('beat-light');
  var minusBtn = document.getElementById('bpm-minus');
  var plusBtn = document.getElementById('bpm-plus');
  var startBtn = document.getElementById('start-btn');
  var stopBtn = document.getElementById('stop-btn');

  function intervalMs() {
    return 60000 / bpm;
  }

  function render() {
    bpmValueEl.textContent = String(bpm);
    beatCountEl.textContent = String(beatCount);
    minusBtn.disabled = bpm <= MIN_BPM;
    plusBtn.disabled = bpm >= MAX_BPM;
    startBtn.disabled = running;
    stopBtn.disabled = !running;
  }

  function flashLight() {
    beatLightEl.classList.add('active');
    if (lightTimeout !== null) {
      clearTimeout(lightTimeout);
    }
    var onTime = Math.min(120, Math.max(40, intervalMs() * 0.4));
    lightTimeout = setTimeout(function () {
      beatLightEl.classList.remove('active');
      lightTimeout = null;
    }, onTime);
  }

  function tick() {
    beatCount += 1;
    beatCountEl.textContent = String(beatCount);
    flashLight();
    scheduleNext();
  }

  function scheduleNext() {
    if (!running) {
      return;
    }
    nextTickAt += intervalMs();
    var delay = nextTickAt - Date.now();
    if (delay < 0) {
      delay = 0;
    }
    timerId = setTimeout(tick, delay);
  }

  function start() {
    if (running) {
      return;
    }
    running = true;
    beatCount = 0;
    beatCountEl.textContent = '0';
    nextTickAt = Date.now();
    render();
    tick();
  }

  function stop() {
    if (!running) {
      return;
    }
    running = false;
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    if (lightTimeout !== null) {
      clearTimeout(lightTimeout);
      lightTimeout = null;
    }
    beatLightEl.classList.remove('active');
    beatCount = 0;
    beatCountEl.textContent = '0';
    render();
  }

  function changeBpm(delta) {
    var next = Math.min(MAX_BPM, Math.max(MIN_BPM, bpm + delta));
    if (next === bpm) {
      return;
    }
    bpm = next;
    render();
    if (running) {
      if (timerId !== null) {
        clearTimeout(timerId);
        timerId = null;
      }
      nextTickAt = Date.now();
      scheduleNext();
    }
  }

  minusBtn.addEventListener('click', function () {
    changeBpm(-1);
  });

  plusBtn.addEventListener('click', function () {
    changeBpm(1);
  });

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  document.addEventListener('keydown', function (event) {
    if (event.code === 'Space' && event.target === document.body) {
      event.preventDefault();
      if (running) {
        stop();
      } else {
        start();
      }
    }
  });

  render();
})();
